solution.code:
function buatMesinPesanan({ db, broker, bayar, stokAwal }) {
  let nomor = 0;
  let urutKirim = 0;
  const antreDlq = [];

  const amplop = (type, correlationId, data) => ({
    id: "msg-" + ++nomor,
    type,
    version: 1,
    correlation_id: correlationId,
    data,
  });
  const keOutbox = (tx, type, orderId, data) => {
    const pesan = amplop(type, orderId, data);
    tx.sisip("outbox", { id: pesan.id, routing_key: type + ".v1", pesan, sent_at: null });
  };
  // Guarded transition: status hanya berpindah bila status sekarang sesuai.
  const pindah = (tx, orderId, dari, ke) => {
    const o = tx.ambil("orders", orderId);
    if (!o || o.status !== dari) return false;
    tx.ubah("orders", orderId, { status: ke });
    return true;
  };

  const handler = {
    // Inventory
    "stock.reserve.v1": (tx, { order_id, sku, qty }) => {
      if (tx.ambil("reservations", order_id)) return;
      const s = tx.ambil("stock", sku);
      if (s && s.available >= qty) {
        tx.ubah("stock", sku, { available: s.available - qty });
        tx.sisip("reservations", { id: order_id, sku, qty, status: "held" });
        keOutbox(tx, "stock.reserved", order_id, { order_id, sku, qty });
      } else {
        keOutbox(tx, "stock.rejected", order_id, { order_id, sku, qty });
      }
    },
    "stock.release.v1": (tx, { order_id }) => {
      const r = tx.ambil("reservations", order_id);
      if (!r || r.status !== "held") return;
      const s = tx.ambil("stock", r.sku);
      tx.ubah("stock", r.sku, { available: s.available + r.qty });
      tx.ubah("reservations", order_id, { status: "released" });
      keOutbox(tx, "stock.released", order_id, { order_id });
    },
    // Payment
    "payment.charge.v1": async (tx, { order_id }) => {
      const hasil = await bayar(order_id);
      keOutbox(tx, hasil === "sukses" ? "payment.succeeded" : "payment.failed", order_id, { order_id });
    },
    // Order: orkestrator saga
    "stock.reserved.v1": (tx, { order_id }) => {
      if (pindah(tx, order_id, "PENDING", "AWAITING_PAYMENT")) keOutbox(tx, "payment.charge", order_id, { order_id });
    },
    "stock.rejected.v1": (tx, { order_id }) => {
      if (pindah(tx, order_id, "PENDING", "CANCELLED")) keOutbox(tx, "order.cancelled", order_id, { order_id });
    },
    "payment.succeeded.v1": (tx, { order_id }) => {
      if (pindah(tx, order_id, "AWAITING_PAYMENT", "CONFIRMED")) keOutbox(tx, "order.confirmed", order_id, { order_id });
    },
    "payment.failed.v1": (tx, { order_id }) => {
      if (pindah(tx, order_id, "AWAITING_PAYMENT", "COMPENSATING")) keOutbox(tx, "stock.release", order_id, { order_id });
    },
    "stock.released.v1": (tx, { order_id }) => {
      if (pindah(tx, order_id, "COMPENSATING", "CANCELLED")) keOutbox(tx, "order.cancelled", order_id, { order_id });
    },
  };

  const siap = db.transaksi(async (tx) => {
    for (const [sku, jumlah] of Object.entries(stokAwal)) tx.sisip("stock", { id: sku, available: jumlah });
  });

  // Konsumen idempoten: id pesan dicatat di transaksi yang sama dengan efeknya.
  // Id dedup: "<konsumen>:<event_id>", jadi satu event boleh diproses sekali oleh tiap konsumen.
  const KONSUMEN = { "stock.reserve.v1": "inventory", "stock.release.v1": "inventory", "payment.charge.v1": "payment" };
  const proses = ({ key, pesan }) =>
    db.transaksi(async (tx) => {
      const h = handler[key];
      if (!h) return;
      const dedup = (KONSUMEN[key] || "order") + ":" + pesan.id;
      if (tx.ambil("processed_events", dedup)) return;
      await h(tx, pesan.data);
      tx.sisip("processed_events", { id: dedup });
    });

  return {
    async checkout({ orderId, sku, qty }) {
      await siap;
      return db.transaksi(async (tx) => {
        const lama = tx.ambil("orders", orderId);
        if (lama) return lama.status;
        tx.sisip("orders", { id: orderId, sku, qty, status: "PENDING" });
        keOutbox(tx, "stock.reserve", orderId, { order_id: orderId, sku, qty });
        return "PENDING";
      });
    },
    async relay() {
      await siap;
      const terkirim = [];
      try {
        for (const baris of db.lihat("outbox")) {
          if (baris.sent_at !== null) continue;
          await broker.publish(baris.routing_key, baris.pesan);
          terkirim.push(baris.id);
        }
      } catch (e) {
        // Broker gagal: berhenti, sisanya dicoba di relay berikutnya.
      }
      if (terkirim.length) {
        await db.transaksi(async (tx) => {
          for (const id of terkirim) tx.ubah("outbox", id, { sent_at: ++urutKirim });
        });
      }
      return terkirim.length;
    },
    async jalankan() {
      await this.relay();
      for (let m = broker.ambil(); m; m = broker.ambil()) {
        for (let percobaan = 1; percobaan <= 3; percobaan++) {
          try {
            await proses(m);
            break;
          } catch (e) {
            // ponytail: retry langsung tanpa jeda; sistem nyata memakai backoff lewat antrean retry.
            if (percobaan === 3) antreDlq.push({ ...m, alasan: String(e.message), percobaan });
          }
        }
        await this.relay();
      }
    },
    status(orderId) {
      const o = db.lihat("orders").find((x) => x.id === orderId);
      return o ? o.status : null;
    },
    stok(sku) {
      const s = db.lihat("stock").find((x) => x.id === sku);
      return s ? s.available : null;
    },
    dlq() {
      return antreDlq.slice();
    },
  };
}

