// Tiruan kecil untuk proyek ini. Di sistem nyata: buatDb = PostgreSQL, buatBroker = RabbitMQ, bayar = gateway pembayaran.
function sama(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

// buatDb(): tabel = array baris dengan `id` unik. db.transaksi(async (tx) => {...}) berjalan satu per satu;
// bila fn melempar error, semua tulisannya dibatalkan. tx.sisip melempar "duplicate key" seperti PRIMARY KEY.
// db.gagalkanBerikutnya(): transaksi berikutnya gagal saat commit (meniru koneksi putus).
function buatDb() {
  let data = {};
  let antre = Promise.resolve();
  let gagal = false;
  const tabel = (t) => (data[t] ??= []);
  const salin = (b) => JSON.parse(JSON.stringify(b));
  const tx = {
    sisip(t, baris) {
      if (tabel(t).some((b) => b.id === baris.id)) throw new Error(`duplicate key ${t}.id = ${baris.id}`);
      tabel(t).push(salin(baris));
    },
    ambil(t, id) { const b = tabel(t).find((b) => b.id === id); return b ? salin(b) : null; },
    ubah(t, id, perubahan) {
      const b = tabel(t).find((b) => b.id === id);
      if (!b) throw new Error(`baris ${t}.id = ${id} tidak ada`);
      Object.assign(b, salin(perubahan));
    },
    semua(t) { return tabel(t).map(salin); },
  };
  return {
    transaksi(fn) {
      const jalan = antre.then(async () => {
        const cadangan = JSON.stringify(data);
        try {
          const hasil = await fn(tx);
          if (gagal) { gagal = false; throw new Error("koneksi database putus saat commit"); }
          return hasil;
        } catch (e) { data = JSON.parse(cadangan); throw e; }
      });
      antre = jalan.catch(() => {});
      return jalan;
    },
    lihat(t) { return (data[t] ?? []).map(salin); },
    gagalkanBerikutnya() { gagal = true; },
  };
}

// buatBroker(): satu antrean di memori. publish(key, pesan) menyalin pesan, ambil() mengembalikan { key, pesan } atau null.
// matikan()/hidupkan() meniru broker mati, putusSetelah(n) gagal setelah n publish,
// kirimDuplikat(true) membuat setiap pesan diantarkan dua kali (meniru redelivery).
function buatBroker() {
  const antrean = [];
  const terkirim = [];
  let mati = false;
  let sisa = Infinity;
  let duplikat = false;
  const salin = (x) => JSON.parse(JSON.stringify(x));
  return {
    terkirim,
    async publish(key, pesan) {
      if (mati || sisa <= 0) throw new Error("broker tidak bisa dihubungi");
      sisa--;
      terkirim.push({ key, pesan: salin(pesan) });
      antrean.push({ key, pesan: salin(pesan) });
      if (duplikat) antrean.push({ key, pesan: salin(pesan) });
    },
    ambil() { return antrean.shift() ?? null; },
    matikan() { mati = true; },
    hidupkan() { mati = false; sisa = Infinity; },
    putusSetelah(n) { sisa = n; },
    kirimDuplikat(v) { duplikat = v; },
  };
}

// buatBayar({ gagal, sementara }): gateway palsu. Mengembalikan "sukses" atau "gagal" (kartu ditolak).
// sementara = { orderId: n } membuat n panggilan pertama untuk pesanan itu melempar error sementara (timeout).
function buatBayar({ gagal = [], sementara = {} } = {}) {
  const sisa = { ...sementara };
  const bayar = async (orderId) => {
    bayar.panggilan.push(orderId);
    if (sisa[orderId] > 0) { sisa[orderId]--; throw new Error("gateway timeout"); }
    return gagal.includes(orderId) ? "gagal" : "sukses";
  };
  bayar.panggilan = [];
  return bayar;
}

const STATUS = ["PENDING", "AWAITING_PAYMENT", "CONFIRMED", "COMPENSATING", "CANCELLED"];

function siapkan({ stok = { "SEPATU-01": 100 }, gagal, sementara } = {}) {
  const db = buatDb();
  const broker = buatBroker();
  const bayar = buatBayar({ gagal, sementara });
  const m = buatMesinPesanan({ db, broker, bayar, stokAwal: stok });
  return { db, broker, bayar, m };
}

