function cocokTopik(pola, routingKey) {
  const p = pola.split(".");
  const k = routingKey.split(".");
  const cocok = (i, j) => {
    if (i === p.length) return j === k.length;
    if (p[i] === "#") return cocok(i + 1, j) || (j < k.length && cocok(i, j + 1));
    if (j === k.length) return false;
    return (p[i] === "*" || p[i] === k[j]) && cocok(i + 1, j + 1);
  };
  return cocok(0, 0);
}

function antarkan(pesan, ikatan) {
  const hasil = [];
  for (const b of ikatan) {
    if (cocokTopik(b.pola, pesan.routingKey) && !hasil.includes(b.antrian)) hasil.push(b.antrian);
  }
  return hasil;
}

