async function jalankanRelay(db, broker) {
  const antre = await db.transaksi(async (tx) => tx.semua("outbox").filter((b) => b.sent_at === null));
  let terkirim = 0;
  for (const b of antre) {
    try {
      await broker.publish(b.routing_key, b.payload);
    } catch (e) {
      break; // coba lagi di putaran relay berikutnya
    }
    await db.transaksi(async (tx) => tx.ubah("outbox", b.id, { sent_at: jam.sekarang() }));
    terkirim += 1;
  }
  return terkirim;
}

