solution.code:
async function jalankanSaga(langkah, konteks) {
  const log = [];
  const selesai = [];
  for (const l of langkah) {
    try {
      await l.aksi(konteks);
    } catch (e) {
      log.push("gagal:" + l.nama);
      let tertahan = false;
      for (const s of selesai.reverse()) {
        if (!s.kompensasi) continue;
        let berhasil = false;
        for (let coba = 1; coba <= 3 && !berhasil; coba++) {
          try {
            await s.kompensasi(konteks);
            berhasil = true;
          } catch (e2) {
            // coba lagi; kompensasi harus aman diulang
          }
        }
        log.push((berhasil ? "kompensasi:" : "kompensasi-gagal:") + s.nama);
        if (!berhasil) tertahan = true;
      }
      return { status: tertahan ? "COMPENSATING" : "CANCELLED", log };
    }
    log.push("aksi:" + l.nama);
    selesai.push(l);
  }
  return { status: "CONFIRMED", log };
}

