    async tulis(sku, nilai) { await jeda(); if (nilai < 0) throw new Error("CHECK (sisa >= 0) dilanggar"); this.terjual += (stok[sku] ?? 0) - nilai; stok[sku] = nilai; },
    async kurangiJika(sku, n) {
      await jeda();
      if ((stok[sku] ?? 0) < n) return 0;
      stok[sku] -= n;
      this.terjual += n;
      return 1;
    },
    lihat(sku) { return stok[sku]; },
  };
}

