const POLA = /^00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/;

function bacaTraceparent(header) {
  if (typeof header !== "string") return null;
  const m = POLA.exec(header);
  if (!m) return null;
  const [, traceId, parentId, flags] = m;
  if (/^0+$/.test(traceId) || /^0+$/.test(parentId)) return null;
  return { traceId, parentId, flags };
}

function turunanTraceparent(header, spanIdBaru) {
  const t = bacaTraceparent(header);
  if (!t) return null;
  return ["00", t.traceId, spanIdBaru, t.flags].join("-");
}

