function ambilPath(obj, path) {
  let x = obj;
  for (const k of path.split(".")) {
    if (x === null || typeof x !== "object") return undefined;
    x = x[k];
  }
  return x;
}

function tipeDari(v) {
  if (Array.isArray(v)) return "array";
  return typeof v;
}

function cekKontrak(skema, pesan) {
  const salah = [];
  const periksa = (aturan, wajib) => {
    for (const [path, tipe] of Object.entries(aturan || {})) {
      const v = ambilPath(pesan, path);
      if (v === undefined || v === null) {
        if (wajib) salah.push(path + " hilang");
      } else if (tipeDari(v) !== tipe) {
        salah.push(path + " harus " + tipe);
      }
    }
  };
  periksa(skema.wajib, true);
  periksa(skema.opsional, false);
  return salah;
}

